import java.math.BigDecimal
import java.math.RoundingMode

class Ledger {
    private val balances = HashMap<String, BigDecimal>()
    private val log = HashMap<String, MutableList<BigDecimal>>()

    fun openAccount(id: String, initial: BigDecimal = BigDecimal.ZERO) {
        if (balances.containsKey(id)) {
            throw IllegalArgumentException("Account already exists: $id")
        }
        val normalized = normalize(initial)
        balances[id] = normalized
        log[id] = mutableListOf()
    }

    fun balance(id: String): BigDecimal {
        val b = balances[id] ?: throw NoSuchElementException("Unknown account: $id")
        return b.setScale(2, RoundingMode.HALF_UP)
    }

    fun transfer(from: String, to: String, amount: BigDecimal) {
        if (amount.signum() <= 0) {
            throw IllegalArgumentException("Amount must be positive")
        }
        val amt = normalize(amount)
        val fromBalance = balances[from] ?: throw NoSuchElementException("Unknown account: $from")
        val toBalance = balances[to] ?: throw NoSuchElementException("Unknown account: $to")

        if (fromBalance < amt) {
            throw IllegalStateException("insufficient funds")
        }

        balances[from] = fromBalance.subtract(amt)
        log.getValue(from).add(amt.negate())
        balances[to] = toBalance.add(amt)
        log.getValue(to).add(amt)
    }

    fun history(id: String): List<BigDecimal> {
        val entries = log[id] ?: throw NoSuchElementException("Unknown account: $id")
        return entries.map { it.setScale(2, RoundingMode.HALF_UP) }
    }

    private fun normalize(value: BigDecimal): BigDecimal {
        if (value.scale() > 2) {
            // Check if there are non-zero digits beyond the second decimal place
            val truncated = value.setScale(2, RoundingMode.DOWN)
            if (!truncated.equals(value)) {
                throw IllegalArgumentException("Amount must have at most 2 decimal places")
            }
        }
        return value.setScale(2, RoundingMode.HALF_UP)
    }

    companion object {
        fun split(total: BigDecimal, n: Int): List<BigDecimal> {
            if (n <= 0) {
                throw IllegalArgumentException("n must be positive")
            }
            val normalizedTotal = total.setScale(2, RoundingMode.HALF_UP)
            // Work in cents to avoid floating point issues
            val totalCents = normalizedTotal.movePointRight(2).toLong()
            val baseCents = totalCents / n
            val remainder = (totalCents % n).toInt()

            val result = ArrayList<BigDecimal>(n)
            // Larger parts first: the first 'remainder' parts get baseCents + 1 cent
            for (i in 0 until n) {
                val cents = if (i < remainder) baseCents + 1 else baseCents
                result.add(BigDecimal(cents).movePointLeft(2))
            }
            return result
        }
    }
}
