    if (map.isEmpty()) {
        sb.append("{}")
        return
    }
    if (indent == 0) {
        sb.append('{')
        var first = true
        for ((k, v) in map) {
            if (!first) sb.append(',')
            first = false
            val key = k as? String ?: throw IllegalArgumentException("Map keys must be strings")
            writeString(sb, key)
            sb.append(':')
            writeValue(sb, v, indent, level + 1)
        }
        sb.append('}')
    } else {
        sb.append('{')
        val innerIndent = " ".repeat(indent * (level + 1))
        val outerIndent = " ".repeat(indent * level)
        var first = true
        for ((k, v) in map) {
            if (!first) sb.append(',')
            first = false
            sb.append('\n')
            sb.append(innerIndent)
            val key = k as? String ?: throw IllegalArgumentException("Map keys must be strings")
            writeString(sb, key)
            sb.append(": ")
            writeValue(sb, v, indent, level + 1)
        }
        sb.append('\n')
        sb.append(outerIndent)
        sb.append('}')
    }
}

