```kotlin
sealed class Token {
    abstract val pos: Int
    data class Ident(val name: String, override val pos: Int) : Token()
    data class Str(val value: String, override val pos: Int) : Token()
    data class Num(val value: Double, override val pos: Int) : Token()
    data class Op(val symbol: String, override val pos: Int) : Token()
    data class Paren(val open: Boolean, override val pos: Int) : Token()
}

class TokenizeException(message: String, val pos: Int) : Exception(message)

fun tokenize(input: String): List<Token> {
    val tokens = mutableListOf<Token>()
    var i = 0
    val n = input.length

    while (i < n) {
        val c = input[i]

        // Skip whitespace
        if (c == ' ' || c == '\t' || c == '\n') {
            i++
            continue
        }

        // Identifiers: [A-Za-z_][A-Za-z0-9_.]*
        if (c.isLetter() || c == '_') {
            val start = i
            while (i < n && (input[i].isLetterOrDigit() || input[i] == '_' || input[i] == '.')) {
                i++
            }
            tokens.add(Token.Ident(input.substring(start, i), start))
            continue
        }

        // Numbers: optional leading '-' only when previous token is absent, an Op, or an opening paren
        if (c.isDigit() || c == '-') {
            val start = i
            var negative = false

            if (c == '-') {
                // Check if the previous token allows a negative number
                val prevToken = tokens.lastOrNull()
                val canBeNegative = when (prevToken) {
                    null -> true
                    is Token.Op -> true
                    is Token.Paren -> prevToken.open
                    else -> false
                }
                if (!canBeNegative) {
                    throw TokenizeException("Unexpected '-'", start)
                }
                negative = true
                i++
                // Now we must have a digit
                if (i >= n || !input[i].isDigit()) {
                    throw TokenizeException("Expected digit after '-'", start)
                }
            }

            // Parse digits
            while (i < n && input[i].isDigit()) {
                i++
            }

            // Check for fraction part
            if (i < n && input[i] == '.') {
                // .5 is an error (no leading digit before dot) - but we already have at least one digit here
                // 5. is an error (dot followed by non-digit or end)
                i++
                if (i >= n || !input[i].isDigit()) {
                    throw TokenizeException("Malformed number", start)
                }
                while (i < n && input[i].isDigit()) {
                    i++
                }
            }

            val numStr = input.substring(start, i)
            tokens.add(Token.Num(numStr.toDouble(), start))
            continue
        }

        // Strings: single or double quotes
        if (c == '"' || c == '\'') {
            val quote = c
            val start = i
            i++
            val sb = StringBuilder()
            var terminated = false
            while (i < n) {
                val ch = input[i]
                if (ch == '\\') {
                    // Escape sequence
                    if (i + 1 >= n) {
                        throw TokenizeException("Unterminated string", start)
                    }
                    val next = input[i + 1]
                    when (next) {
                        'n' -> sb.append('\n')
                        else -> sb.append(next)
                    }
                    i += 2
                } else if (ch == quote) {
                    terminated = true
                    i++
                    break
                } else {
                    sb.append(ch)
                    i++
                }
            }
            if (!terminated) {
                throw TokenizeException("Unterminated string", start)
            }
            tokens.add(Token.Str(sb.toString(), start))
            continue
        }

        // Parentheses
        if (c == '(') {
            tokens.add(Token.Paren(true, i))
            i++
            continue
        }
        if (c == ')') {
            tokens.add(Token.Paren(false, i))
            i++
            continue
        }

        // Operators: longest match first
        // Two-char operators: == != <= >= && ||
        // One-char operators: < > !
        val twoChar = if (i + 1 < n) input.substring(i, i + 2) else ""
        when (twoChar) {
            "==", "!=", "<=", ">=", "&&", "||" -> {
                tokens.add(Token.Op(twoChar, i))
                i += 2
                continue
            }
        }
        val oneChar = c.toString()
        if (oneChar in setOf("<", ">", "!")) {
            tokens.add(Token.Op(oneChar, i))
            i++
            continue
        }

        // Anything else is an error
        throw TokenizeException("Unexpected character '$c'", i)
    }

    return tokens
}
