import re


def apply_patch(original: str, diff: str) -> str:
    """Apply a unified diff to original text and return the patched result."""

    # Split original into lines keeping newline characters
    def splitlines_keepends(text):
        if not text:
            return []
        lines = []
        i = 0
        n = len(text)
        while i < n:
            nl = text.find('\n', i)
            if nl == -1:
                lines.append(text[i:])
                break
            else:
                lines.append(text[i:nl + 1])
                i = nl + 1
        return lines

    original_lines = splitlines_keepends(original)

    # Find all hunks in the diff
    hunk_pattern = re.compile(r'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@')

    lines = diff.split('\n')
    if lines and lines[-1] == '':
        # The last element is empty due to trailing newline; keep it for processing
        pass

    hunks = []  # list of (old_start, old_count, new_start, new_count, body_lines)

    i = 0
    n = len(lines)
    while i < n:
