        m = hunk_pattern.match(line)
        if m:
            old_start = int(m.group(1))
            old_count = int(m.group(2)) if m.group(2) is not None else 1
            new_start = int(m.group(3))
            new_count = int(m.group(4)) if m.group(4) is not None else 1

            # Collect body lines
            body_lines = []
            j = i + 1
            while j < n:
                bl = lines[j]
                if bl.startswith(' ') or bl.startswith('-') or bl.startswith('+'):
                    body_lines.append(bl)
                    j += 1
                elif bl == '\\':
                    # Check if next line is "No newline at end of file"
                    if j + 1 < n and lines[j + 1].strip() == 'No newline at end of file':
                        body_lines.append('\\')
                        j += 2
                    else:
                        break
                elif bl.startswith('@@'):
                    break
                elif bl == '':
                    # Could be an empty line in the diff (context with no content) or end
                    # An empty line that is just '' could be a context line with empty content
                    # But actually, context lines start with space. An empty string here
                    # means it's not a valid body line.
                    break
                else:
                    break

            hunks.append((old_start, old_count, new_start, new_count, body_lines))
            i = j
        else:
