def flatten(obj, sep=".") -> dict:
    if not isinstance(obj, dict):
        raise TypeError("Top-level object must be a dict")

    result = {}

    def _flatten_value(value, prefix, result):
        """Recursively flatten a value at the given prefix."""
        if isinstance(value, dict):
            if len(value) == 0:
                result[prefix] = {}
            else:
                for key, val in value.items():
                    if not isinstance(key, str):
                        raise ValueError(f"Key must be a string: {key!r}")
                    if sep in key:
                        raise ValueError(f"Key contains separator: {key!r}")
                    new_prefix = f"{prefix}{sep}{key}" if prefix else key
                    _flatten_value(val, new_prefix, result)
        elif isinstance(value, list):
            if len(value) == 0:
                result[prefix] = []
            else:
                for i, item in enumerate(value):
                    new_prefix = f"{prefix}{sep}{i}"
                    _flatten_value(item, new_prefix, result)
        else:
            result[prefix] = value

    for key, val in obj.items():
        if not isinstance(key, str):
            raise ValueError(f"Key must be a string: {key!r}")
        if sep in key:
            raise ValueError(f"Key contains separator: {key!r}")
        new_prefix = f"{sep}{key}" if prefix := "" else key
        _flatten_value(val, new_prefix, result)

    return result


def unflatten(flat: dict, sep=".") -> dict:
    if not isinstance(flat, dict):
        raise TypeError("Input must be a dict")

    def _is_valid_index(s):
        """Check if s is a non-negative integer without leading zeros."""
        if not isinstance(s, str) or len(s) == 0:
            return False
        if not s.isdigit():
            return False
        if len(s) > 1 and s[0] == '0':
            return False
        return True

    # Build the tree structure
    root = {}

    for key, value in flat.items():
        parts = key.split(sep)

        node = root
        for i, part in enumerate(parts):
            if i == len(parts) - 1:
                # Last segment: set the leaf value
                if isinstance(node, dict):
                    if part in node:
                        existing = node[part]
                        if not isinstance(existing, (dict, list)):
                            raise ValueError(f"Conflict at key {key!r}")
                    node[part] = value
                elif isinstance(node, list):
                    if not _is_valid_index(part):
                        raise ValueError(f"Invalid index segment: {part!r}")
                    idx = int(part)
                    while len(node) <= idx:
                        node.append(None)
                    if node[idx] is not None and not isinstance(node[idx], (dict, list)):
                        raise ValueError(f"Conflict at key {key!r}")
                    node[idx] = value
            else:
                # Intermediate segment: navigate/create container
                if isinstance(node, dict):
                    if part in node:
                        child = node[part]
                        if not isinstance(child, (dict, list)):
                            raise ValueError(f"Conflict at key {key!r}")
                        node = child
                    else:
                        # Create a placeholder; will be converted to list or dict later
                        node[part] = {}
                        node = node[part]
                elif isinstance(node, list):
                    if not _is_valid_index(part):
                        raise ValueError(f"Invalid index segment: {part!r}")
                    idx = int(part)
                    while len(node) <= idx:
                        node.append({})
                    node = node[idx]

    # Convert placeholder dicts to lists where appropriate, and validate density
    def _finalize(node):
        if isinstance(node, dict):
            if len(node) == 0:
                return {}

            # Check if all keys are valid indices forming a dense sequence 0..n-1
            all_indices = True
            indices = []
            for k in node.keys():
                if _is_valid_index(k):
                    indices.append(int(k))
                else:
                    all_indices = False
                    break

            if all_indices and len(indices) > 0:
                # Check density: must be exactly 0..n-1
                if sorted(indices) == list(range(len(node))):
                    # Convert to list
                    lst = [None] * len(node)
                    for k, v in node.items():
                        lst[int(k)] = _finalize(v)
                    return lst

            # It's a dict; finalize children
            result = {}
            for k, v in node.items():
                result[k] = _finalize(v)
            return result
        elif isinstance(node, list):
            return [_finalize(item) for item in node]
        else:
            return node

    return _finalize(root)
