```python
"""A small expression language interpreter.

Grammar (lowest to highest precedence):
1. `a ? b : c` conditional, right-associative; `a` is true when non-zero. Only the chosen branch is evaluated.
2. `||` then `&&` (short-circuit; result is 1 or 0).
3. comparisons `== != < <= > >=`, non-associative: `1 < 2 < 3` is an error. Result 1 or 0.
4. `+ -` left-associative.
5. `* / %` left-associative. `/` on two ints gives an int when it divides exactly, else a float. `%` follows Python semantics.
6. unary `-`, `+`, `!` (`!x` is 1 if x == 0 else 0).
7. `^` power, right-associative, binds tighter than unary minus on its left: `-2^2` is -4, `2^-1` is 0.5, `2^3^2` is 512.
8. atoms: integer literals (`42`), decimal literals (`1.5`, `.5`, `2.`), identifiers `[A-Za-z_][A-Za-z0-9_]*` looked up in `env`, function calls `min(...)`, `max(...)` (1 or more args), `abs(x)`, and parentheses.

Whitespace is ignored between tokens. Errors: raise `ZeroDivisionError` for division or modulo by zero,
`NameError` for unknown variables or functions, and `SyntaxError` for anything malformed (including wrong
argument counts for `abs`, empty input, trailing tokens, a lone `=`, `&`, `|`).
"""

from __future__ import annotations


# Token types
TOK_INT = "INT"
TOK_FLOAT = "FLOAT"
TOK_IDENT = "IDENT"
TOK_OP = "OP"       # arithmetic and comparison operators
TOK_LPAREN = "LPAREN"
TOK_RPAREN = "RPAREN"
TOK_COMMA = "COMMA"
TOK_QUESTION = "QUESTION"
TOK_COLON = "COLON"
TOK_EOF = "EOF"


class _Token:
    __slots__ = ("kind", "value")

    def __init__(self, kind: str, value):
        self.kind = kind
        self.value = value

    def __repr__(self) -> str:
        return f"Token({self.kind!r}, {self.value!r})"


# Two-character operators (must be checked before one-char)
_TWO_CHAR_OPS = ("==", "!=", "<=", ">=")
_ONE_CHAR_OPS = ("+", "-", "*", "/", "%", "^", "<", ">", "!", "&", "|", "?", ":")


def _tokenize(expr: str) -> list[_Token]:
    tokens: list[_Token] = []
    i = 0
    n = len(expr)

    while i < n:
        ch = expr[i]

        # Skip whitespace
        if ch.isspace():
            i += 1
            continue

        # Two-character operators
        if i + 1 < n and expr[i : i + 2] in _TWO_CHAR_OPS:
            tokens.append(_Token(TOK_OP, expr[i : i + 2]))
            i += 2
            continue

        # One-character operators / punctuation
        if ch in "+-*/%^<>=!&|?":
            tokens.append(_Token(TOK_OP, ch))
            i += 1
            continue

        if ch == "(":
            tokens.append(_Token(TOK_LPAREN, "("))
            i += 1
            continue

        if ch == ")":
            tokens.append(_Token(TOK_RPAREN, ")"))
            i += 1
            continue

        if ch == ",":
            tokens.append(_Token(TOK_COMMA, ","))
            i += 1
            continue

        # Numbers: integer or decimal literals
        if ch.isdigit() or (ch == "." and i + 1 < n and expr[i + 1].isdigit()):
            start = i
            # Integer part
            while i < n and expr[i].isdigit():
                i += 1
            # Decimal part
            if i < n and expr[i] == ".":
                i += 1
                while i < n and expr[i].isdigit():
                    i += 1
            text = expr[start:i]
            if "." in text:
                tokens.append(_Token(TOK_FLOAT, float(text)))
            else:
                tokens.append(_Token(TOK_INT, int(text)))
            continue

        # Identifiers / function names
        if ch.isalpha() or ch == "_":
            start = i
            while i < n and (expr[i].isalnum() or expr[i] == "_"):
                i += 1
            tokens.append(_Token(TOK_IDENT, expr[start:i]))
            continue

        raise SyntaxError(f"Unexpected character {ch!r} at position {i}")

    tokens.append(_Token(TOK_EOF, None))
    return tokens


class _Parser:
    def __init__(self, tokens: list[_Token], env: dict[str, float] | None):
        self.tokens = tokens
        self.pos = 0
        self.env = env if env is not None else {}

    def peek(self) -> _Token:
        return self.tokens[self.pos]

    def advance(self) -> _Token:
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, kind: str, value=None) -> _Token:
        tok = self.peek()
        if tok.kind != kind or (value is not None and tok.value != value):
            raise SyntaxError(f"Expected {kind} {value!r} but got {tok!r}")
        return self.advance()

    def parse(self) -> int | float:
        result = self.parse_conditional()
        if self.peek().kind != TOK_EOF:
            raise SyntaxError(f"Unexpected token {self.peek()!r} after expression")
        return result

    # 1. Conditional: a ? b : c  (right-associative)
    def parse_conditional(self) -> int | float:
        cond = self.parse_or()
        if self.peek().kind == TOK_QUESTION:
            self.advance()  # consume '?'
            true_branch = self.parse_conditional()  # right-associative: parse full conditional for true branch
            self.expect(TOK_COLON)  # expect ':'
            false_branch = self.parse_conditional()  # right-associative: parse full conditional for false branch
            if cond != 0:
                return true_branch
            else:
                return false_branch
        return cond

    # 2. || (lowest of logical)
    def parse_or(self) -> int | float:
        left = self.parse_and()
        while self._peek_op("||"):
            self.advance()
            right = self.parse_and()
            if left != 0:
                left = 1
            else:
                left = 1 if right != 0 else 0
        return left

    # 2. && (higher than ||)
    def parse_and(self) -> int | float:
        left = self.parse_comparison()
        while self._peek_op("&&"):
            self.advance()
            right = self.parse_comparison()
            if left == 0:
                left = 0
            else:
                left = 1 if right != 0 else 0
        return left

    # 3. Comparisons (non-associative)
    def parse_comparison(self) -> int | float:
        left = self.parse_additive()
        tok = self.peek()
        if tok.kind == TOK_OP and tok.value in ("==", "!=", "<", "<=", ">", ">="):
            self.advance()
            right = self.parse_additive()
            op = tok.value
            if op == "==":
                return 1 if left == right else 0
            elif op == "!=":
                return 1 if left != right else 0
            elif op == "<":
                return 1 if left < right else 0
            elif op == "<=":
                return 1 if left <= right else 0
            elif op == ">":
                return 1 if left > right else 0
            elif op == ">=":
                return 1 if left >= right else 0
        return left

    # 4. Additive: + - (left-associative)
    def parse_additive(self) -> int | float:
        left = self.parse_multiplicative()
        while True:
            tok = self.peek()
            if tok.kind == TOK_OP and tok.value in ("+", "-"):
                self.advance()
                right = self.parse_multiplicative()
                if tok.value == "+":
                    left = left + right
                else:
                    left = left - right
            else:
                break
        return left

    # 5. Multiplicative: * / % (left-associative)
    def parse_multiplicative(self) -> int | float:
        left = self.parse_unary()
        while True:
            tok = self.peek()
            if tok.kind == TOK_OP and tok.value in ("*", "/", "%"):
                self.advance()
                right = self.parse_unary()
                if tok.value == "*":
                    left = left * right
                elif tok.value == "/":
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    # If both are int and divides exactly, result is int
                    if isinstance(left, int) and isinstance(right, int):
                        if left % right == 0:
                            left = left // right
                        else:
                            left = left / right
                    else:
                        left = left / right
                elif tok.value == "%":
                    if right == 0:
                        raise ZeroDivisionError("modulo by zero")
                    left = left % right
            else:
                break
        return left

    # 6. Unary: - + ! (prefix)
    def parse_unary(self) -> int | float:
        tok = self.peek()
        if tok.kind == TOK_OP and tok.value in ("-", "+", "!"):
            self.advance()
            operand = self.parse_unary()
            if tok.value == "-":
                return -operand
            elif tok.value == "+":
                return +operand
            elif tok.value == "!":
                return 1 if operand == 0 else 0
        return self.parse_power()

    # 7. Power: ^ (right-associative)
    def parse_power(self) -> int | float:
        base = self.parse_atom()
        if self.peek().kind == TOK_OP and self.peek().value == "^":
            self.advance()
            exponent = self.parse_unary()  # right-associative: parse unary (which can include more ^ via recursion)
            return base ** exponent
        return base

    # 8. Atoms: literals, identifiers, function calls, parentheses
    def parse_atom(self) -> int | float:
        tok = self.peek()

        if tok.kind == TOK_INT:
            self.advance()
            return tok.value

        if tok.kind == TOK_FLOAT:
            self.advance()
            return tok.value

        if tok.kind == TOK_IDENT:
            name = tok.value
            self.advance()
            # Check for function call
            if self.peek().kind == TOK_LPAREN:
                self.advance()  # consume '('
                args = self._parse_arg_list()
                self.expect(TOK_RPAREN)  # expect ')'
                return self._call_function(name, args)
            else:
                # Variable lookup
                if name in self.env:
                    return self.env[name]
                raise NameError(f"Name {name!r} is not defined")

        if tok.kind == TOK_LPAREN:
            self.advance()  # consume '('
            expr = self.parse_conditional()
            self.expect(TOK_RPAREN)  # expect ')'
            return expr

        raise SyntaxError(f"Unexpected token {tok!r}")

    def _parse_arg_list(self) -> list[int | float]:
        args: list[int | float] = []
        if self.peek().kind == TOK_RPAREN:
            return args  # empty argument list (will be validated later)
        args.append(self.parse_conditional())
        while self.peek().kind == TOK_COMMA:
            self.advance()  # consume ','
            args.append(self.parse_conditional())
        return args

    def _call_function(self, name: str, args: list[int | float]) -> int | float:
        if name == "min":
            if len(args) < 1:
                raise SyntaxError("min() requires at least 1 argument")
            result = args[0]
            for a in args[1:]:
                if a < result:
                    result = a
            return result
        elif name == "max":
            if len(args) < 1:
                raise SyntaxError("max() requires at least 1 argument")
            result = args[0]
            for a in args[1:]:
                if a > result:
                    result = a
            return result
        elif name == "abs":
            if len(args) != 1:
                raise SyntaxError("abs() requires exactly 1 argument")
            return abs(args[0])
        else:
            raise NameError(f"Function {name!r} is not defined")

    def _peek_op(self, op: str) -> bool:
        tok = self.peek()
        if tok.kind == TOK_OP and tok.value == op:
            return True
        # Special handling for || and && which are two-char sequences of | and &
        # Actually, the tokenizer already handles these as single tokens, so this shouldn't be needed.
        # But let's make sure: the tokenizer checks two-char ops first, so "||" and "&&" are single tokens.
        return False


def evaluate(expr: str, env: dict[str, float] | None = None) -> int | float:
    """Evaluate an expression in the small expression language.

    Args:
        expr: The expression string to evaluate.
        env: Optional dictionary of variable names to float values.

    Returns:
        The result as an int or float.

    Raises:
        ZeroDivisionError: For division or modulo by zero.
        NameError: For unknown variables or functions.
        SyntaxError: For malformed expressions.
    """
    if not expr.strip():
        raise SyntaxError("Empty expression")

    tokens = _tokenize(expr)
    parser = _Parser(tokens, env)
    return parser.parse()
