        if tok.kind != kind or (value is not None and tok.value != value):
            raise SyntaxError(f"Expected {kind} {value!r} but got {tok!r}")
        return self.advance()

    def parse(self) -> int | float:
        result = self.parse_conditional()
        if self.peek().kind != TOK_EOF:
            raise SyntaxError(f"Unexpected token {self.peek()!r} after expression")
        return result

    # 1. Conditional: a ? b : c (right-associative)
    def parse_conditional(self) -> int | float:
        cond = self.parse_or()
        if self.peek().kind == TOK_OP and self.peek().value == "?":
            self.advance()  # consume '?'
            true_branch = self.parse_conditional()
            self.expect(TOK_COLON)
            false_branch = self.parse_conditional()
            if cond != 0:
                return true_branch
            else:
                return false_branch
        return cond

    # 2. || (lowest of logical, short-circuit)
    def parse_or(self) -> int | float:
        left = self.parse_and()
        while self.peek().kind == TOK_OP and self.peek().value == "||":
            self.advance()
            right = self.parse_and()
            if left != 0:
                left = 1
            else:
                left = 1 if right != 0 else 0
        return left

    # 2. && (higher than ||, short-circuit)
    def parse_and(self) -> int | float:
        left = self.parse_comparison()
        while self.peek().kind == TOK_OP and self.peek().value == "&&":
            self.advance()
            right = self.parse_comparison()
            if left == 0:
                left = 0
            else:
                left = 1 if right != 0 else 0
        return left

    # 3. Comparisons (non-associative)
    def parse_comparison(self) -> int | float:
        left = self.parse_additive()
        tok = self.peek()
        if tok.kind == TOK_OP and tok.value in ("==", "!=", "<", "<=", ">", ">="):
            self.advance()
            right = self.parse_additive()
            op = tok.value
            if op == "==":
                return 1 if left == right else 0
            elif op == "!=":
                return 1 if left != right else 0
            elif op == "<":
                return 1 if left < right else 0
            elif op == "<=":
                return 1 if left <= right else 0
            elif op == ">":
                return 1 if left > right else 0
            elif op == ">=":
                return 1 if left >= right else 0
        return left

    # 4. Additive: + - (left-associative)
    def parse_additive(self) -> int | float:
        left = self.parse_multiplicative()
        while True:
            tok = self.peek()
            if tok.kind == TOK_OP and tok.value in ("+", "-"):
                self.advance()
                right = self.parse_multiplicative()
                if tok.value == "+":
                    left = left + right
                else:
                    left = left - right
            else:
                break
        return left

    # 5. Multiplicative: * / % (left-associative)
    def parse_multiplicative(self) -> int | float:
        left = self.parse_unary()
        while True:
            tok = self.peek()
            if tok.kind == TOK_OP and tok.value in ("*", "/", "%"):
                self.advance()
                right = self.parse_unary()
                if tok.value == "*":
                    left = left * right
                elif tok.value == "/":
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    if isinstance(left, int) and isinstance(right, int):
                        if left % right == 0:
                            left = left // right
                        else:
                            left = left / right
                    else:
                        left = left / right
                elif tok.value == "%":
                    if right == 0:
                        raise ZeroDivisionError("modulo by zero")
                    left = left % right
            else:
                break
        return left

    # 6. Unary: - + ! (prefix)
    def parse_unary(self) -> int | float:
        tok = self.peek()
        if tok.kind == TOK_OP and tok.value in ("-", "+", "!"):
            self.advance()
            operand = self.parse_unary()
            if tok.value == "-":
                return -operand
            elif tok.value == "+":
                return +operand
            elif tok.value == "!":
                return 1 if operand == 0 else 0
        return self.parse_power()

    # 7. Power: ^ (right-associative)
    def parse_power(self) -> int | float:
        base = self.parse_atom()
        if self.peek().kind == TOK_OP and self.peek().value == "^":
            self.advance()
            exponent = self.parse_unary()
            return base ** exponent
        return base

    # 8. Atoms
    def parse_atom(self) -> int | float:
        tok = self.peek()

        if tok.kind == TOK_INT:
            self.advance()
            return tok.value

        if tok.kind == TOK_FLOAT:
            self.advance()
            return tok.value

        if tok.kind == TOK_IDENT:
            name = tok.value
            self.advance()
            if self.peek().kind == TOK_LPAREN:
                self.advance()
                args = self._parse_arg_list()
                self.expect(TOK_RPAREN)
                return self._call_function(name, args)
            else:
                if name in self.env:
                    return self.env[name]
                raise NameError(f"Name {name!r} is not defined")

        if tok.kind == TOK_LPAREN:
            self.advance()
            expr = self.parse_conditional()
            self.expect(TOK_RPAREN)
            return expr

        raise SyntaxError(f"Unexpected token {tok!r}")

    def _parse_arg_list(self) -> list[int | float]:
        args: list[int | float] = []
        if self.peek().kind == TOK_RPAREN:
            return args
        args.append(self.parse_conditional())
        while self.peek().kind == TOK_COMMA:
            self.advance()
            args.append(self.parse_conditional())
        return args

    def _call_function(self, name: str, args: list[int | float]) -> int | float:
        if name == "min":
            if len(args) < 1:
                raise SyntaxError("min() requires at least 1 argument")
            result = args[0]
            for a in args[1:]:
                if a < result:
                    result = a
            return result
        elif name == "max":
            if len(args) < 1:
                raise SyntaxError("max() requires at least 1 argument")
            result = args[0]
            for a in args[1:]:
                if a > result:
                    result = a
            return result
        elif name == "abs":
            if len(args) != 1:
                raise SyntaxError("abs() requires exactly 1 argument")
            return abs(args[0])
        else:
            raise NameError(f"Function {name!r} is not defined")


def evaluate(expr: str, env: dict[str, float] | None = None) -> int | float:
    """Evaluate an expression in the small expression language."""
    if not expr.strip():
        raise SyntaxError("Empty expression")

    tokens = _tokenize(expr)
    parser = _Parser(tokens, env)
    return parser.parse()
