def route(grid: list[str]) -> tuple[int, str] | None:
    if not grid:
        raise ValueError("Empty grid")

    R = len(grid)
    C = len(grid[0])

    # Validate grid
    s_count = 0
    e_count = 0
    start = None
    end = None
    pads = {}  # letter -> list of (r, c)

    for r in range(R):
        row = grid[r]
        if len(row) != C:
            raise ValueError("Ragged rows")
        for c in range(C):
            ch = row[c]
            if ch == 'S':
                s_count += 1
                start = (r, c)
            elif ch == 'E':
                e_count += 1
                end = (r, c)
            elif ch == '#' or ch == '.':
                pass
            elif ch.isdigit() and '1' <= ch <= '9':
                pass
            elif 'a' <= ch <= 'z':
                if ch not in pads:
                    pads[ch] = []
                pads[ch].append((r, c))
            else:
                raise ValueError(f"Unknown character: {ch}")

    if s_count != 1:
        raise ValueError("Not exactly one S")
    if e_count != 1:
        raise ValueError("Not exactly one E")

    for ch, positions in pads.items():
        if len(positions) == 1 or len(positions) > 2:
            raise ValueError(f"Letter {ch} appears {len(positions)} times, must be 0 or 2")

    # Build pad mapping: (r, c) -> other (r, c)
    pad_map = {}
    for ch, positions in pads.items():
        if len(positions) == 2:
            pad_map[positions[0]] = positions[1]
            pad_map[positions[1]] = positions[0]

    def get_cost(r, c):
        ch = grid[r][c]
        if ch == 'S' or ch == 'E':
            return 1
        elif ch == '.':
            return 1
        elif ch.isdigit() and '1' <= ch <= '9':
            return int(ch)
        elif 'a' <= ch <= 'z':
            return 1
        else:
            return 0  # shouldn't happen for valid cells

    # Dijkstra with lexicographic tie-breaking on move string
    # State: (r, c)
    # We want to find the path from start to end that minimizes cost, then lex order of moves.

    import heapq

    # dist[r][c] = minimum cost to reach (r,c)
    # best_path[r][c] = lexicographically smallest move string among paths with minimum cost

    INF = float('inf')
    dist = [[INF] * C for _ in range(R)]
    best_path = [[""] * C for _ in range(R)]

    start_r, start_c = start
    end_r, end_c = end

    dist[start_r][start_c] = 0
    best_path[start_r][start_c] = ""

    # Priority queue: (cost, move_string, r, c)
    # We use a heap. Python's heapq compares tuples lexicographically, so we can push (cost, moves, r, c).
    # But moves strings can be long; comparing them is O(len). This might be slow for large grids.

    # Alternative: Use Dijkstra where we process nodes in order of cost, and for each node, 
    # we keep the best (lex smallest) move string among all shortest-cost paths to it.

    # Let's use a priority queue with (cost, moves, r, c). When we pop a state, if its cost > dist[r][c], skip.
    # If cost == dist[r][c] and moves < best_path[r][c], update and continue.
    # But this could lead to many entries in the heap.

    # Better approach: Standard Dijkstra but when relaxing an edge, if we find a strictly better cost, update.
    # If we find the same cost but a lex smaller move string, also update.

    # The issue is that with lex tie-breaking, we might need to re-process nodes. Let's think...

    # Actually, for Dijkstra to work correctly with this tie-breaking, we can use the following:
    # When we pop (cost, moves, r, c) from the heap:
    #   if cost > dist[r][c]: skip
    #   if cost == dist[r][c] and moves >= best_path[r][c]: skip
    #   else: process neighbors

    # This should work because once we've processed a node with its best (cost, moves), any subsequent 
    # entry for the same node will either have higher cost or worse moves.

    heap = [(0, "", start_r, start_c)]

    while heap:
        cost, moves, r, c = heapq.heappop(heap)

        if cost > dist[r][c]:
            continue
        if cost == dist[r][c] and moves >= best_path[r][c]:
            continue

        # Process this state
        if (r, c) == end:
            return (cost, moves)

        for dr, dc, move in [(-1, 0, 'U'), (1, 0, 'D'), (0, -1, 'L'), (0, 1, 'R')]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C:
                if grid[nr][nc] == '#':
                    continue
                ncost = cost + get_cost(nr, nc)
                nmoves = moves + move
                if ncost < dist[nr][nc]:
                    dist[nr][nc] = ncost
                    best_path[nr][nc] = nmoves
                    heapq.heappush(heap, (ncost, nmoves, nr, nc))
                elif ncost == dist[nr][nc] and nmoves < best_path[nr][nc]:
                    best_path[nr][nc] = nmoves
                    heapq.heappush(heap, (ncost, nmoves, nr, nc))

        # Teleport move
        if (r, c) in pad_map:
            tr, tc = pad_map[(r, c)]
            ncost = cost + 2
            nmoves = moves + 'T'
            if ncost < dist[tr][tc]:
                dist[tr][tc] = ncost
                best_path[tr][tc] = nmoves
                heapq.heappush(heap, (ncost, nmoves, tr, tc))
            elif ncost == dist[tr][tc] and nmoves < best_path[tr][tc]:
                best_path[tr][tc] = nmoves
                heapq.heappush(heap, (ncost, nmoves, tr, tc))

    return None
