import re


def load_ini(text: str) -> dict[str, dict[str, str]]:
    lines = text.split('\n')
    sections: dict[str, dict[str, str]] = {}
    current_section = None
    last_entry_key = None  # (section, key) of the last entry for continuation

    i = 0
    n = len(lines)

    while i < n:
        raw_line = lines[i]
        line_num = i + 1

        stripped = raw_line.strip()

        # Blank line
        if not stripped:
            last_entry_key = None
            i += 1
            continue

        # Comment line (starts with # or ; after optional whitespace)
        if stripped.startswith('#') or stripped.startswith(';'):
            last_entry_key = None
            i += 1
            continue

        # Continuation line: starts with whitespace and follows an entry
        if raw_line[0] in (' ', '\t') and last_entry_key is not None:
            section, key = last_entry_key
            continuation_value = _process_continuation(raw_line, line_num)
            sections[section][key] += '\n' + continuation_value
            i += 1
            continue

        # Section header
        if stripped.startswith('['):
            if not stripped.endswith(']'):
                raise ValueError(f"line {line_num}: unclosed section header")
            name = stripped[1:-1].strip()
            current_section = name
            if current_section not in sections:
                sections[current_section] = {}
            last_entry_key = None
            i += 1
            continue

        # Entry line (key = value or key: value)
        # Check if it's a continuation with no preceding entry
        if raw_line[0] in (' ', '\t') and last_entry_key is None:
