            sections[current_section] = {}

        sections[current_section][key] = processed_value
        last_entry_key = (current_section, key)
        i += 1

    # Remove empty section "" if it has no keys
    if "" in sections and not sections[""]:
        del sections[""]

    # Interpolation
    for section_name in sections:
        for key in sections[section_name]:
            resolved = _resolve_interpolation(sections, section_name, key, set())
            sections[section_name][key] = resolved

