    value = _strip_inline_comment(stripped)

    # If the value is fully quoted, remove quotes and process escapes
    if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
        inner = value[1:-1]
        inner = inner.replace('\\"', '"')
        return inner

    return value


def _parse_value(stripped: str, line_num: int) -> str:
    """Check for unterminated quotes in the raw stripped line."""
    if _has_unterminated_quote(stripped):
        raise ValueError(f"line {line_num}: unterminated quote")
    return stripped


def _has_unterminated_quote(s: str) -> bool:
