    in_quotes = False
    i = 0
    while i < len(s):
        ch = s[i]
        if ch == '\\' and in_quotes and i + 1 < len(s) and s[i + 1] == '"':
            i += 2
            continue
        if ch == '"':
            in_quotes = not in_quotes
        i += 1
    return in_quotes


def _strip_inline_comment(value: str) -> str:
    """Remove inline comments ( ; or # preceded by whitespace, unless inside quotes)."""
    in_quotes = False
    i = 0
    while i < len(value):
        ch = value[i]
        if ch == '\\' and in_quotes and i + 1 < len(value) and value[i + 1] == '"':
            i += 2
            continue
        if ch == '"':
            in_quotes = not in_quotes
        elif not in_quotes:
            # Check for inline comment: whitespace followed by ; or #
            if ch in (' ', '\t') and i + 1 < len(value):
                next_ch = value[i + 1]
                if next_ch in (';', '#'):
                    return value[:i].rstrip()
        i += 1
    return value


def _process_value(raw_value: str, line_num: int) -> str:
    """Process a raw value string: strip inline comments, handle quotes."""
    # First check for unterminated quote in the full value
    if _has_unterminated_quote(raw_value):
        raise ValueError(f"line {line_num}: unterminated quote")

    # Strip inline comment
    value = _strip_inline_comment(raw_value)

    # Trim
    value = value.strip()

    # If fully wrapped in double quotes, remove quotes and process escapes
    if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
        inner = value[1:-1]
        inner = inner.replace('\\"', '"')
        return inner

    return value


def _resolve_interpolation(sections: dict[str, dict[str, str]], section: str, key: str, resolving: set) -> str:
    """Resolve ${key} and ${section:key} references recursively."""
    if (section, key) in resolving:
        raise ValueError(f"reference cycle detected for {section}:{key}")

    resolving.add((section, key))

    value = sections[section][key]

    # Find all references: ${...}
    def replace_match(match):
        ref_content = match.group(1)

        if ':' in ref_content:
            ref_section, ref_key = ref_content.split(':', 1)
            ref_section = ref_section.strip()
            ref_key = ref_key.strip().lower()

            if ref_section not in sections or ref_key not in sections[ref_section]:
                raise ValueError(f"undefined reference: ${{{ref_content}}}")

            resolved = _resolve_interpolation(sections, ref_section, ref_key, resolving)
        else:
            ref_key = ref_content.strip().lower()

            if key not in sections[section] or ref_key != key and ref_key not in sections[section]:
                # Check if the key exists in the same section
                if ref_key not in sections[section]:
                    raise ValueError(f"undefined reference: ${{{ref_content}}}")

            resolved = _resolve_interpolation(sections, section, ref_key, resolving)

        return resolved

    # Handle $$ first (literal $), then ${...} references
    # We need to be careful: $$ should become $, and ${...} should be resolved
    result = []
    i = 0
    while i < len(value):
        if value[i] == '$':
            if i + 1 < len(value) and value[i + 1] == '$':
                # Literal $
                result.append('$')
                i += 2
            elif i + 1 < len(value) and value[i + 1] == '{':
                # Find the closing }
                end = value.find('}', i + 2)
                if end == -1:
                    raise ValueError(f"unterminated reference in {section}:{key}")
                ref_content = value[i + 2:end]
                match = re.match(r'\$\{(.+)\}', value[i:i + end - i + 1])
                resolved = replace_match(re.Match(None, None, None, None, ref_content) if False else _make_match(ref_content))
                result.append(resolved)
                i = end + 1
            else:
                result.append('$')
                i += 1
        else:
            result.append(value[i])
            i += 1

    resolving.discard((section, key))

    return ''.join(result)


def _make_match(ref_content: str):
    """Create a mock match object for internal use."""
    class MockMatch:
        def __init__(self, content):
            self._content = content
        def group(self, n):
            if n == 1:
                return self._content
            raise ValueError("invalid group")
    return MockMatch(ref_content)
