    if s == "":
        raise ValueError("Empty identifier")
    if len(s) > 1 and s[0] == "0":
        raise ValueError(f"Leading zero in numeric identifier: {s}")
    return int(s)


def _parse_prerelease(s: str) -> Optional[str]:
