        if not isinstance(other, Version):
            return NotImplemented
        return self.key <= other.key

    def __gt__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self.key > other.key

    def __ge__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self.key >= other.key


def _parse_numeric(s: str) -> int:
    """Parse a numeric part with no leading zeros."""
    if s == "":
        raise ValueError("Empty numeric part")
    if len(s) > 1 and s[0] == "0":
        raise ValueError(f"Leading zero in numeric part: {s}")
    return int(s)


def _validate_prerelease(s: str) -> Optional[str]:
    """Validate prerelease string."""
    if s is None or s == "":
        return None
    ids = s.split(".")
    for ident in ids:
        if not re.match(r'^[0-9A-Za-z-]+$', ident):
            raise ValueError(f"Invalid prerelease identifier: {ident}")
        if ident.isdigit():
            if len(ident) > 1 and ident[0] == "0":
                raise ValueError(f"Leading zero in numeric prerelease identifier: {ident}")
    return s


def _validate_build(s: str) -> Optional[str]:
    """Validate build metadata string."""
    if s is None or s == "":
        return None
    ids = s.split(".")
    for ident in ids:
        if not re.match(r'^[0-9A-Za-z-]+$', ident):
            raise ValueError(f"Invalid build identifier: {ident}")
    return s


def parse(v: str) -> Version:
    """Parse a SemVer 2.0.0 version string (requires MAJOR.MINOR.PATCH)."""
    if not isinstance(v, str):
        raise ValueError("Input must be a string")

    s = v.strip()
    if s == "":
        raise ValueError("Empty version string")

    # Strip leading 'v' or '='
    if s[0] in ('v', '='):
        s = s[1:]

    if s == "":
        raise ValueError("Empty version after prefix")

    # Split off build metadata
    build = None
    if "+" in s:
        parts = s.split("+", 1)
        s = parts[0]
        build_str = parts[1]
        build = _validate_build(build_str)
        if build is None:
            raise ValueError("Empty build metadata")

    # Split off prerelease
    prerelease = None
    if "-" in s:
        idx = s.rfind("-")
        s_core = s[:idx]
        pre_str = s[idx + 1:]
        prerelease = _validate_prerelease(pre_str)
        if prerelease is None:
            raise ValueError("Empty prerelease")
    else:
        s_core = s

    # Parse MAJOR.MINOR.PATCH — all three required
    parts = s_core.split(".")
    if len(parts) != 3:
        raise ValueError(f"Invalid version format (need MAJOR.MINOR.PATCH): {s_core}")

    try:
        major = _parse_numeric(parts[0])
        minor = _parse_numeric(parts[1])
        patch = _parse_numeric(parts[2])
    except ValueError as e:
        raise ValueError(f"Invalid version: {v}") from e

    return Version(major, minor, patch, prerelease, build)


@dataclass
class Comparator:
    op: str  # '<', '<=', '>', '>=', '='
    version: Version

    def matches(self, v: Version) -> bool:
        if self.op == "<":
            return v < self.version
        elif self.op == "<=":
            return v <= self.version
        elif self.op == ">":
            return v > self.version
        elif self.op == ">=":
            return v >= self.version
        elif self.op == "=":
            return v == self.version
        return False


def _parse_version_parts(s: str) -> Tuple[Optional[int], Optional[int], Optional[int], Optional[str]]:
    """Parse version parts for range comparators, allowing X-ranges."""
    s = s.strip()
    if s == "":
        raise ValueError("Empty version in comparator")

    # Strip leading v or =
    if s[0] in ('v', '='):
        s = s[1:]

    if s == "":
        raise ValueError("Empty version after prefix")

    # Split off build (ignored in ranges) and prerelease
    build_str = None
    if "+" in s:
        parts = s.split("+", 1)
        s = parts[0]
        build_str = parts[1]
        _validate_build(build_str)

    prerelease = None
    if "-" in s:
        idx = s.rfind("-")
        s_core = s[:idx]
        pre_str = s[idx + 1:]
        prerelease = _validate_prerelease(pre_str)
    else:
        s_core = s

    # Parse M.m.p with X support
    parts = s_core.split(".")
    if len(parts) > 3:
        raise ValueError(f"Too many version parts: {s_core}")

    major = None
    minor = None
    patch = None

    x_re = re.compile(r'^[xX*]$')

    if len(parts) >= 1 and not x_re.match(parts[0]):
        major = _parse_numeric(parts[0])
    elif len(parts) >= 1:
        major = None

    if len(parts) >= 2 and not x_re.match(parts[1]):
        minor = _parse_numeric(parts[1])
    elif len(parts) >= 2:
        minor = None

    if len(parts) >= 3 and not x_re.match(parts[2]):
        patch = _parse_numeric(parts[2])
    elif len(parts) >= 3:
        patch = None

    return major, minor, patch, prerelease


def _expand_partial_version(s: str, op: str) -> List[Comparator]:
    """Expand a possibly partial version with an operator into comparators."""
    major, minor, patch, prerelease = _parse_version_parts(s)

    if major is None and minor is None and patch is None:
        # Fully wildcarded like * or x — matches anything
        return [Comparator(">=", Version(0, 0, 0)), Comparator("<", Version(999999, 999999, 999999))]

    if major is not None and minor is not None and patch is not None:
        v = Version(major, minor, patch, prerelease)
        return [Comparator(op, v)]

    # Partial version handling
    if major is None:
        raise ValueError(f"Invalid partial version: {s}")

    if minor is None:
        # Like "1" or "1.x" — means >=1.0.0 <2.0.0
        if op == ">":
            return [Comparator(">=", Version(major + 1, 0, 0))]
        elif op == "<":
            return [Comparator("<", Version(major, 0, 0))]
        elif op == ">=":
            return [Comparator(">=", Version(major, 0, 0)), Comparator("<", Version(major + 1, 0, 0))]
        elif op == "<=":
            return [Comparator("<", Version(major + 1, 0, 0))]
        else:
            return [Comparator(">=", Version(major, 0, 0)), Comparator("<", Version(major + 1, 0, 0))]

    # Major and minor specified
    if patch is None:
        # Like "1.2" or "1.2.x" — means >=1.2.0 <1.3.0
        if op == ">":
            return [Comparator(">=", Version(major, minor + 1, 0))]
        elif op == "<":
            return [Comparator("<", Version(major, minor, 0))]
        elif op == ">=":
            return [Comparator(">=", Version(major, minor, 0)), Comparator("<", Version(major, minor + 1, 0))]
        elif op == "<=":
            return [Comparator("<", Version(major, minor + 1, 0))]
        else:
            return [Comparator(">=", Version(major, minor, 0)), Comparator("<", Version(major, minor + 1, 0))]

    # Should not reach here
    v = Version(major, minor, patch, prerelease)
    return [Comparator(op, v)]


def _parse_tilde(s: str) -> List[Comparator]:
    """Parse tilde range."""
    s = s.strip()
    major, minor, patch, prerelease = _parse_version_parts(s)

    if major is None:
        raise ValueError(f"Invalid tilde range: {s}")

    if minor is None:
        # ~1 means >=1.0.0 <2.0.0
        return [Comparator(">=", Version(major, 0, 0)), Comparator("<", Version(major + 1, 0, 0))]

    if patch is None:
        # ~1.2 means >=1.2.0 <1.3.0
        return [Comparator(">=", Version(major, minor, 0)), Comparator("<", Version(major, minor + 1, 0))]

    # ~1.2.3 means >=1.2.3 <1.3.0
    return [Comparator(">=", Version(major, minor, patch, prerelease)), Comparator("<", Version(major, minor + 1, 0))]


def _parse_caret(s: str) -> List[Comparator]:
    """Parse caret range."""
    s = s.strip()
    major, minor, patch, prerelease = _parse_version_parts(s)

    if major is None:
        raise ValueError(f"Invalid caret range: {s}")

    if minor is None:
        # ^1 means >=1.0.0 <2.0.0
        return [Comparator(">=", Version(major, 0, 0)), Comparator("<", Version(major + 1, 0, 0))]

    if patch is None:
        if major == 0 and minor == 0:
            # ^0.0.x means >=0.0.0 <0.1.0
            return [Comparator(">=", Version(0, 0, 0)), Comparator("<", Version(0, 1, 0))]
        elif major == 0:
            # ^0.x means >=0.0.0 <1.0.0
            return [Comparator(">=", Version(0, 0, 0)), Comparator("<", Version(1, 0, 0))]
        else:
            # ^1.2.x means >=1.2.0 <2.0.0
            return [Comparator(">=", Version(major, minor, 0)), Comparator("<", Version(major + 1, 0, 0))]

    # Full version specified
    if major == 0:
        if minor == 0:
            # ^0.0.3 means >=0.0.3 <0.0.4
            return [Comparator(">=", Version(0, 0, patch, prerelease)), Comparator("<", Version(0, 0, patch + 1))]
        else:
            # ^0.2.3 means >=0.2.3 <0.3.0
            return [Comparator(">=", Version(0, minor, patch, prerelease)), Comparator("<", Version(0, minor + 1, 0))]
    else:
        # ^1.2.3 means >=1.2.3 <2.0.0
        return [Comparator(">=", Version(major, minor, patch, prerelease)), Comparator("<", Version(major + 1, 0, 0))]


def _parse_hyphen(s: str) -> List[Comparator]:
    """Parse hyphen range like '1.2.3 - 2.3.4'."""
    parts = s.split(" - ")
    if len(parts) != 2:
        raise ValueError(f"Invalid hyphen range: {s}")

    lower_str = parts[0].strip()
    upper_str = parts[1].strip()

    if lower_str == "" or upper_str == "":
        raise ValueError(f"Invalid hyphen range (empty bound): {s}")

    # Parse lower bound (fill zeros for partial)
    major, minor, patch, prerelease = _parse_version_parts(lower_str)
    if major is None:
        major = 0
    if minor is None:
        minor = 0
    if patch is None:
        patch = 0
    lower = Version(major, minor, patch, prerelease)

    # Parse upper bound
    up_major, up_minor, up_patch, up_prerelease = _parse_version_parts(upper_str)

    if up_major is None:
        raise ValueError(f"Invalid hyphen range upper bound: {upper_str}")

    if up_minor is None:
        # Upper bound like "2" means <3.0.0
        upper_comparators = [Comparator("<", Version(up_major + 1, 0, 0))]
    elif up_patch is None:
        # Upper bound like "2.3" means <2.4.0
        upper_comparators = [Comparator("<", Version(up_major, up_minor + 1, 0))]
    else:
        # Full upper bound, inclusive
        upper_comparators = [Comparator("<=", Version(up_major, up_minor, up_patch, up_prerelease))]

    return [Comparator(">=", lower)] + upper_comparators


def _parse_comparator(s: str) -> List[Comparator]:
    """Parse a single comparator string, returning a list of comparators."""
    s = s.strip()
    if s == "":
        raise ValueError("Empty comparator")

    # Check for tilde
    if s.startswith("~"):
        return _parse_tilde(s[1:])

    # Check for caret
    if s.startswith("^"):
        return _parse_caret(s[1:])

    # Check for operators
    op = "="
    rest = s
    if s.startswith("<="):
        op = "<="
        rest = s[2:]
    elif s.startswith(">="):
        op = ">="
        rest = s[2:]
    elif s.startswith("<"):
        op = "<"
        rest = s[1:]
    elif s.startswith(">"):
        op = ">"
        rest = s[1:]
    elif s.startswith("="):
        op = "="
        rest = s[1:]

    rest = rest.strip()
    if rest == "":
        raise ValueError(f"Missing version in comparator: {s}")

    comparators = _expand_partial_version(rest, op)
    return comparators


def _parse_set(s: str) -> List[Comparator]:
    """Parse a single comparator set (space-separated comparators)."""
    s = s.strip()
    if s == "" or s == "*":
        return []

    # Check for hyphen range
    if " - " in s:
        return _parse_hyphen(s)

    # Split into individual comparators by whitespace
    tokens = s.split()
    comparators = []
    for token in tokens:
        if token == "*":
            continue  # wildcard matches anything, no constraint
        comparators.extend(_parse_comparator(token))

    return comparators


def _parse_range(rng: str) -> List[List[Comparator]]:
    """Parse a range string into a list of comparator sets."""
    rng = rng.strip()
    if rng == "":
        return [[]]  # Empty range matches anything

    # Split on ||
    parts = rng.split("||")
    sets = []
    for part in parts:
        comparators = _parse_set(part)
        sets.append(comparators)
    return sets


def _set_matches(sets_comparators: List[Comparator], v: Version) -> bool:
    """Check if a version matches a single comparator set."""
    # Prerelease rule: a version with a prerelease only satisfies a set
    # if some comparator in that set has a version with the same M.m.p and a prerelease
    if v.prerelease is not None:
        has_matching_prerelease = False
        for comp in sets_comparators:
            if (comp.version.major == v.major and
                    comp.version.minor == v.minor and
                    comp.version.patch == v.patch and
                    comp.version.prerelease is not None):
                has_matching_prerelease = True
                break
        if not has_matching_prerelease:
            return False

    # All comparators must match
    for comp in sets_comparators:
        if not comp.matches(v):
            return False
    return True


def satisfies(version: str, rng: str) -> bool:
    """Check if a version string satisfies a range string."""
    v = parse(version)
    sets = _parse_range(rng)

    for set_comparators in sets:
        if _set_matches(set_comparators, v):
            return True
    return False


def max_satisfying(versions: List[str], rng: str) -> Optional[str]:
    """Return the highest version string that satisfies the range, or None."""
    best = None
    best_version = None

    for v_str in versions:
        try:
            v = parse(v_str)
        except ValueError:
            continue

        if satisfies(v_str, rng):
            if best_version is None or v > best_version:
                best_version = v
                best = v_str

    return best
