        header_parsed = 1

        # Determine target index
        if (colname ~ /^#[0-9]+$/) {
            num_str = substr(colname, 2)
            target_idx = num_str + 1 # 1-based

            if (target_idx < 1 || target_idx > num_header_fields) {
                print "Error: column index #" num_str " out of range" > "/dev/stderr"
                exit 3
            }
        } else {
            found = 0
            for (f = 0; f < num_header_fields; f++) {
                if (header[f] == colname) {
                    target_idx = f + 1 # 1-based
                    found = 1
                    break
                }
            }
            if (!found) {
                print "Error: unknown column '" colname "'" > "/dev/stderr"
                exit 3
            }
        }
    } else {
        # Data row
        val = ""
        if (target_idx - 1 < num_fields) {
            val = fields[target_idx - 1]
        } else {
            val = "" # Fewer fields than header -> empty
        }

        if (summary == 0) {
            # Print value, replacing newlines with literal \n
            gsub(/\n/, "\\n", val)
            print val
        } else {
            # Check numeric
            if (val ~ /^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)$/) {
                num = val + 0
                count++
                sum += num
                if (count == 1 || num < min_val) min_val = num
                if (count == 1 || num > max_val) max_val = num
            }
        }
    }
}
AWKEOF

# Execute the awk script
if [ -n "$FILE" ]; then
    awk -v DELIM="$DELIM" -v COLNAME="$COLUMN" -v SUMMARY="$SUMMARY" "$AWK_SCRIPT" < "$FILE"
else
    awk -v DELIM="$DELIM" -v COLNAME="$COLUMN" -v SUMMARY="$SUMMARY" "$AWK_SCRIPT"
fi

exit $?
