#!/usr/bin/env bash
set -euo pipefail

if [[ $# -ne 1 ]]; then
    echo "Usage: $0 DIR" >&2
    exit 1
fi

DIR="$1"

if [[ ! -d "$DIR" ]]; then
    echo "Error: '$DIR' is not a directory" >&2
    exit 1
fi

# Use find to list regular files (not following symlinks), excluding .git and node_modules directories
# Print each file path with a NUL separator, then process with awk
find "$DIR" -type f \
    ! -path '*/.git/*' \
    ! -path '*/node_modules/*' \
    -print0 2>/dev/null | \
awk 'BEGIN { RS="\0"; FS="" } 
{
    # Get the basename: everything after the last /
    path = $0
    slash = 0
    for (i = length(path); i >= 1; i--) {
        if (substr(path, i, 1) == "/") {
            slash = i
            break
        }
    }
    if (slash > 0) {
        basename = substr(path, slash + 1)
    } else {
        basename = path
    }

    # Find the last dot in basename
    dotpos = 0
    for (i = length(basename); i >= 1; i--) {
        if (substr(basename, i, 1) == ".") {
            dotpos = i
            break
        }
    }

    # Determine extension
    if (dotpos == 0 || dotpos == 1) {
        ext = "(none)"
    } else {
        ext = tolower(substr(basename, dotpos + 1))
    }

    count[ext]++
}
END {
    for (ext in count) {
        printf "%s %d\n", ext, count[ext]
    }
}' | sort -t' ' -k2,2nr -k1,1
