#!/usr/bin/env bash
# solution.sh FILE - convert a dotenv file into shell code safe to eval in bash

set -u

if [ $# -ne 1 ]; then
    echo "usage: $0 FILE" >&2
    exit 1
fi

FILE="$1"

if [ ! -f "$FILE" ] || [ ! -r "$FILE" ]; then
    echo "$FILE:0: invalid line" >&2
    exit 1
fi

# We'll use awk to parse the file and produce output.
# On error, awk prints to stderr and exits with code 1, and we ensure no stdout is produced.

awk -v FILENAME_VAR="$FILE" '
function emit_key(key, val) {
    # Store value for key; if key already seen, replace value but keep position of LAST occurrence
    if (!(key in pos)) {
        order[++n] = key
        pos[key] = n
    } else {
        # Key already exists; update its position to current line number
        # But we need to keep it at the LATER position. So we remove old entry and add new one.
        # Actually, simpler: just store the value in valmap[key], and track order of first appearance.
        # When a key repeats, we want it printed once at its LAST occurrence position.
        # Approach: store all entries in arrays indexed by line number, then at END, for each key,
        # find the last line number where it appeared, and output at that position.
    }
    valmap[key] = val
    lastline[key] = NR
}

function single_quote_escape(s) {
    # Escape single quotes for bash single-quoted string: '\'' 
    gsub(/'\''/, "'\\''\\''", s)
    return s
}

BEGIN {
    n = 0
    err = 0
}

{
    line = $0

    # Strip trailing \r if present (handle CRLF)
    sub(/\r$/, "", line)

    # Check for blank lines: only spaces/tabs or empty
    if (line ~ /^[[:space:]]*$/) next

    # Check for comment lines: first non-blank char is #
    stripped = line
    sub(/^[[:space:]]+/, "", stripped)
    if (stripped ~ /^#/) next

    # Now parse the line
    # Remove leading whitespace
    sub(/^[[:space:]]+/, "", line)

    # Check for optional "export " prefix
    prefix = ""
    rest = line
    if (line ~ /^export[[:space:]]+/) {
        prefix = "export"
        sub(/^export[[:space:]]+/, "", rest)
    }

    # Now rest should be KEY=VALUE
    # Find the first unquoted '='
    # Key must match [A-Za-z_][A-Za-z0-9_]* with no spaces around =

    # Extract key: everything before the first '='
    eqpos = index(rest, "=")
    if (eqpos == 0) {
        print FILENAME_VAR ":" NR ": invalid line" > "/dev/stderr"
        err = 1
        exit 1
    }

    key = substr(rest, 1, eqpos - 1)
    value_part = substr(rest, eqpos + 1)

    # Validate key: must match [A-Za-z_][A-Za-z0-9_]*
    if (key !~ /^[A-Za-z_][A-Za-z0-9_]*$/) {
        print FILENAME_VAR ":" NR ": invalid line" > "/dev/stderr"
        err = 1
        exit 1
    }

    # Check no spaces around '=': the char before = in rest is part of key (already validated),
    # and we need to ensure value_part does not start with space or tab? 
    # Actually "no spaces around =" means the key has no trailing space and value has no leading space.
    # Since key is validated as [A-Za-z_][A-Za-z0-9_]*, it cannot have trailing spaces.
    # For value: if it starts with a space or tab, that would mean there's a space after =.
    # But wait - the spec says "no spaces around =", so if there is a space right after =, it is invalid?
    # Let me re-read: "KEY=VALUE, KEY matching [A-Za-z_][A-Za-z0-9_]*, no spaces around ="
    # This means the format is strictly KEY=VALUE with no spaces. So if value_part starts with space/tab, invalid.

    # Check if value_part starts with space or tab (which would mean space after =)
    if (value_part ~ /^[[:space:]]/) {
        print FILENAME_VAR ":" NR ": invalid line" > "/dev/stderr"
        err = 1
        exit 1
    }

    # Now parse the value
    if (value_part == "") {
        # Empty value - this is valid, empty string
        val = ""
    } else if (substr(value_part, 1, 1) == "\x27") {
        # Single-quoted value
        # Find closing single quote
        rest_after_open = substr(value_part, 2)
        closepos = index(rest_after_open, "\x27")
        if (closepos == 0) {
            print FILENAME_VAR ":" NR ": invalid line" > "/dev/stderr"
            err = 1
            exit 1
        }
        val = substr(rest_after_open, 1, closepos - 1)
        after_close = substr(rest_after_open, closepos + 1)
        # Anything after closing quote must be empty or a comment (optional whitespace then #)
        if (after_close ~ /^[[:space:]]*$/ || after_close ~ /^[[:space:]]*#/) {
            # valid
        } else {
            print FILENAME_VAR ":" NR ": invalid line" > "/dev/stderr"
            err = 1
            exit 1
        }
    } else if (substr(value_part, 1, 1) == "\"") {
        # Double-quoted value
        rest_after_open = substr(value_part, 2)
        # Parse double-quoted string with escape sequences
        val = ""
        i = 1
        len = length(rest_after_open)
        closed = 0
        while (i <= len) {
            c = substr(rest_after_open, i, 1)
            if (c == "\\") {
                if (i < len) {
                    nc = substr(rest_after_open, i + 1, 1)
                    if (nc == "n") {
                        val = val "\n"
                    } else if (nc == "\"") {
                        val = val "\""
                    } else if (nc == "\\") {
                        val = val "\\"
                    } else {
                        # Other escapes stay as is: keep the backslash and the next char
                        val = val "\\" nc
                    }
                    i += 2
                } else {
                    # Backslash at end of string - invalid (unterminated)
                    print FILENAME_VAR ":" NR ": invalid line" > "/dev/stderr"
                    err = 1
                    exit 1
                }
            } else if (c == "\"") {
                closed = 1
                i++
                break
            } else {
                val = val c
                i++
            }
        }
        if (!closed) {
            print FILENAME_VAR ":" NR ": invalid line" > "/dev/stderr"
            err = 1
            exit 1
        }
        after_close = substr(rest_after_open, i)
        # Anything after closing quote must be empty or a comment
        if (after_close ~ /^[[:space:]]*$/ || after_close ~ /^[[:space:]]*#/) {
            # valid
        } else {
            print FILENAME_VAR ":" NR ": invalid line" > "/dev/stderr"
            err = 1
            exit 1
        }
    } else {
        # Unquoted value
        # Taken literally up to an unquoted " #" (space then hash starts a comment)
        # Trailing spaces and tabs are trimmed.
        # "a#b" keeps the hash (only space+hash triggers comment)

        # Find " #" - a space followed by # that is not inside quotes (but this is unquoted, so no quotes)
        # We need to find the first occurrence of " #" where the # starts a comment.
        # The rule: "up to an unquoted ' #' (space then hash starts a comment)"
        # So we look for the pattern: a space character followed by a # character.

        val = value_part
        found_comment = 0
        i = 1
        len = length(val)
        while (i < len) {
            if (substr(val, i, 1) == " " && substr(val, i + 1, 1) == "#") {
                # Found comment start
                val = substr(val, 1, i - 1)
                found_comment = 1
                break
            }
            i++
        }

        # Trim trailing spaces and tabs
        sub(/[[:space:]]+$/, "", val)
    }

    # Store this entry
    emit_key(key, val)
}

END {
    if (err) exit 1

    # Now we need to output each key once, at its LAST occurrence position.
    # Build a map from line number to key for the last occurrence of each key.
    # For each key in valmap, lastline[key] is the line number of its last occurrence.

    # Create an array: out_at[line] = key (for lines where a key has its last occurrence)
    for (key in valmap) {
        ln = lastline[key]
        out_at[ln] = key
    }

    # Now iterate through all line numbers that have entries, in order.
    # We need to collect the sorted line numbers. Since mawk doesn't have asort,
    # we can just iterate from 1 to NR (max line number) and check if out_at[ln] is set.

    maxline = 0
    for (key in valmap) {
        ln = lastline[key]
        if (ln > maxline) maxline = ln
    }

    # Actually, we should iterate through all possible line numbers up to the total number of lines processed.
    # Let us track the total number of lines seen.
    for (ln = 1; ln <= NR; ln++) {
        if (ln in out_at) {
            key = out_at[ln]
            val = valmap[key]
            # Escape single quotes in val for bash single-quoted string
            escaped = single_quote_escape(val)
            printf "export %s=\x27%s\x27\n", key, escaped
        }
    }
}
' "$FILE"

# Check exit status of awk
if [ $? -ne 0 ]; then
    exit 1
fi

exit 0
