#!/usr/bin/env bash

usage() {
    echo "Usage: solution.sh [-n N] [-i]" >&2
}

N=10
IGNORECASE=0

while getopts ":n:i" opt; do
    case "$opt" in
        n)
            N="$OPTARG"
            if ! [[ "$N" =~ ^[0-9]+$ ]] || [ "$N" -le 0 ]; then
                usage
                exit 2
            fi
            ;;
        i)
            IGNORECASE=1
            ;;
        :)
            echo "Option -$OPTARG requires an argument." >&2
            usage
            exit 2
            ;;
        \?)
            echo "Invalid option: -$OPTARG" >&2
            usage
            exit 2
            ;;
    esac
done

if ! [[ "$N" =~ ^[0-9]+$ ]] || [ "$N" -le 0 ]; then
    usage
    exit 2
fi

export IGNORECASE

awk '
BEGIN {
    ic = (ENVIRON["IGNORECASE"] == "1") ? 1 : 0
}
{
    line = $0
    while (match(line, /[A-Za-z0-9\x27]+/)) {
        word = substr(line, RSTART, RLENGTH)
        line = substr(line, RSTART + RLENGTH)

        # Strip leading apostrophes
        while (length(word) > 0 && substr(word, 1, 1) == "\x27") {
            word = substr(word, 2)
        }
        # Strip trailing apostrophes
        while (length(word) > 0 && substr(word, length(word), 1) == "\x27") {
            word = substr(word, 1, length(word) - 1)
        }

        if (word == "") continue

        if (ic) {
            word = tolower(word)
        }

        count[word]++
    }
}
END {
    for (w in count) {
        printf "%d %s\n", count[w], w
    }
}
' | LC_ALL=C sort -t ' ' -k1,1nr -k2,2 | head -n "$N"

exit 0
